import{_ as d,o as r,c as a,a2 as o}from"./chunks/framework.ktMMbWgA.js";const g=JSON.parse('{"title":"期中考试参考答案 — L00–L16","description":"","frontmatter":{},"headers":[],"relativePath":"assessments/exams/midterm-answers.md","filePath":"assessments/exams/midterm-answers.md","lastUpdated":null}'),e={name:"assessments/exams/midterm-answers.md"};function l(n,t,s,h,i,u){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="期中考试参考答案-—-l00–l16" tabindex="-1">期中考试参考答案 — L00–L16 <a class="header-anchor" href="#期中考试参考答案-—-l00–l16" aria-label="Permalink to &quot;期中考试参考答案 — L00–L16&quot;">​</a></h1><blockquote><p>本文件供教师 / 同行评审 / LLM-as-Judge 使用。每题给出 <strong>标准答案 + 评分要点 + 常见错误</strong>。</p><p>严禁向学生发布。</p></blockquote><hr><h2 id="选择题答案" tabindex="-1">选择题答案 <a class="header-anchor" href="#选择题答案" aria-label="Permalink to &quot;选择题答案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题号</th><th>答案</th><th>关键依据</th></tr></thead><tbody><tr><td>Q1</td><td><strong>B</strong></td><td>L01 §6 三个实验共同指向&quot;压缩 + 偏差&quot;统一论断</td></tr><tr><td>Q2</td><td><strong>B</strong></td><td>L02 §4 连接派的&quot;学习能力&quot;诉求</td></tr><tr><td>Q3</td><td><strong>B</strong></td><td>L03 §1 统一框架的&quot;模型 / 损失 / 数据 / 优化器&quot;四要素</td></tr><tr><td>Q4</td><td><strong>C</strong></td><td>L05 §2 表格数据的 GBDT 统治；L04 §6 模型偏置匹配</td></tr><tr><td>Q5</td><td><strong>B</strong></td><td>L07 §2 卷积的两个先验</td></tr><tr><td>Q6</td><td><strong>B</strong></td><td>L11 §3 Word2Vec 的&quot;线性可加语义&quot;</td></tr><tr><td>Q7</td><td><strong>B</strong></td><td>L12 §2.4 缩放因子的方差控制论证（数学推导见 lecture_notes 公式）</td></tr><tr><td>Q8</td><td><strong>B</strong></td><td>L12 §5 Decoder-Only 一统江湖的工程理由</td></tr><tr><td>Q9</td><td><strong>B</strong></td><td>L14 §1 Kaplan 三幂律的核心结论</td></tr><tr><td>Q10</td><td><strong>B</strong></td><td>L16 §3 4-bit 量化的部署经济学</td></tr></tbody></table><p>每题 3 分，无部分分。</p><hr><h2 id="简答题评分要点" tabindex="-1">简答题评分要点 <a class="header-anchor" href="#简答题评分要点" aria-label="Permalink to &quot;简答题评分要点&quot;">​</a></h2><h3 id="q11-system-1-2-主线" tabindex="-1">Q11（System 1/2 主线） <a class="header-anchor" href="#q11-system-1-2-主线" aria-label="Permalink to &quot;Q11（System 1/2 主线）&quot;">​</a></h3><p><strong>满分要点（6 分）</strong>：</p><ul><li>至少识别 2 处后续呼应（L20 推理模型 = System 2 显式化；L30 AI 编程的 completion=S1 / Agentic=S2）</li><li>解释为什么这条线是&quot;主线&quot;——在 4+ 讲中持续被引用</li><li><strong>常见错误</strong>：把 System 1/2 当成&quot;只是 L01 的内容&quot;</li></ul><h3 id="q12-sgd-蒙眼下山" tabindex="-1">Q12（SGD 蒙眼下山） <a class="header-anchor" href="#q12-sgd-蒙眼下山" aria-label="Permalink to &quot;Q12（SGD 蒙眼下山）&quot;">​</a></h3><p><strong>满分要点（6 分）</strong>：</p><ul><li>学习率 = 步长（太大跳过最低点 / 太小走不动）</li><li>batch size = 视野范围（小 batch 噪声大 / 大 batch 估计稳但更新慢）</li><li>batch ×10 → 学习率应大致 ×√10（线性缩放规则的方差版）</li><li><strong>常见错误</strong>：说&quot;batch ×10 → lr ×10&quot;（线性规则在大 batch 下不准）</li></ul><h3 id="q13-归纳偏置反转" tabindex="-1">Q13（归纳偏置反转） <a class="header-anchor" href="#q13-归纳偏置反转" aria-label="Permalink to &quot;Q13（归纳偏置反转）&quot;">​</a></h3><p><strong>满分要点（6 分）</strong>：</p><ul><li>关键变量是<strong>数据规模</strong>：小数据下结构先验有用（CNN 胜）；大数据下模型自己学结构（Transformer 胜）</li><li>引用 ViT 在 JFT-300M 上反超 CNN 的实证</li><li><strong>常见错误</strong>：把两者说成&quot;对立&quot;；正确表述是&quot;在不同规模区间各占优&quot;</li></ul><h3 id="q14-embedding-两次出场" tabindex="-1">Q14（Embedding 两次出场） <a class="header-anchor" href="#q14-embedding-两次出场" aria-label="Permalink to &quot;Q14（Embedding 两次出场）&quot;">​</a></h3><p><strong>满分要点（6 分）</strong>：</p><ul><li>共同点：都是把符号空间映射到连续几何空间</li><li>工程目标差异：L11 是&quot;理解&quot;（语义关系可计算）/ L23 是&quot;检索&quot;（k-NN 可工程化）</li><li><strong>常见错误</strong>：只说&quot;L23 是 L11 的应用&quot;——忽略了 L23 引入的 SBERT / 双塔等专门优化</li></ul><h3 id="q15-chinchilla-vs-kaplan" tabindex="-1">Q15（Chinchilla vs Kaplan） <a class="header-anchor" href="#q15-chinchilla-vs-kaplan" aria-label="Permalink to &quot;Q15（Chinchilla vs Kaplan）&quot;">​</a></h3><p><strong>满分要点（6 分）</strong>：</p><ul><li>Kaplan 主张&quot;模型规模为主、数据可省&quot;</li><li>Chinchilla 修正：模型与数据应<strong>1:20</strong> 比例（70B 模型应配 1.4T tokens）</li><li>实际意义：Llama / Mistral / Qwen 都按 Chinchilla 比例训练，避免 GPT-3 的&quot;过参数欠数据&quot;</li><li><strong>常见错误</strong>：说 Chinchilla 否定了 scaling law（错——它只修正了数据维度）</li></ul><hr><h2 id="思辨题评分量表" tabindex="-1">思辨题评分量表 <a class="header-anchor" href="#思辨题评分量表" aria-label="Permalink to &quot;思辨题评分量表&quot;">​</a></h2><h3 id="q16-神经-符号" tabindex="-1">Q16（神经-符号） <a class="header-anchor" href="#q16-神经-符号" aria-label="Permalink to &quot;Q16（神经-符号）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>评分维度</th><th>4 分</th><th>7 分</th><th>10 分</th></tr></thead><tbody><tr><td>立场清晰度</td><td>立场模糊 / 复述课程</td><td>立场清晰但缺论据</td><td>清晰立场 + 至少 2 条独立论据</td></tr><tr><td>引用准确度</td><td>误引或泛泛</td><td>正确引用 AlphaGeometry</td><td>+ 引用 Marcus 批评 / Sutton &quot;苦涩教训&quot;</td></tr><tr><td>折衷讨论</td><td>单边论述</td><td>提到对立观点</td><td>给出&quot;什么场景哪种胜出&quot;的具体边界</td></tr></tbody></table><h3 id="q17-开源-闭源" tabindex="-1">Q17（开源/闭源） <a class="header-anchor" href="#q17-开源-闭源" aria-label="Permalink to &quot;Q17（开源/闭源）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>评分维度</th><th>4 分</th><th>7 分</th><th>10 分</th></tr></thead><tbody><tr><td>三个角度的覆盖</td><td>只覆盖 1 个</td><td>覆盖 2 个</td><td>三个全覆盖 + 各自给出可证伪指标</td></tr><tr><td>2030 比例预测</td><td>拍脑袋</td><td>给出比例 + 简短理由</td><td>给出比例 + 历史类比（如 Linux vs Windows）+ 关键变量识别</td></tr><tr><td>数据引用</td><td>无数据</td><td>引用一组数据（如 Hugging Face top-trending）</td><td>多源数据 + 自己识别的偏差</td></tr></tbody></table><hr><h2 id="跨讲整合题评分-q18-·-20-分" tabindex="-1">跨讲整合题评分（Q18 · 20 分） <a class="header-anchor" href="#跨讲整合题评分-q18-·-20-分" aria-label="Permalink to &quot;跨讲整合题评分（Q18 · 20 分）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>评分维度</th><th>5 分</th><th>12 分</th><th>18+ 分</th></tr></thead><tbody><tr><td><strong>四条线索覆盖</strong></td><td>仅覆盖 1–2 条</td><td>全覆盖但平面化</td><td>全覆盖 + 识别&quot;压缩&quot;在 4 个层面的<strong>不同形式</strong></td></tr><tr><td><strong>论证连贯性</strong></td><td>4 段并列</td><td>有过渡词但逻辑薄</td><td>用一条主线串起（如&quot;从有损到可微&quot;演化）</td></tr><tr><td><strong>批判深度</strong></td><td>全盘同意命题 A</td><td>提到 1 个反例</td><td>提出&quot;哪一环最薄弱&quot;的具体批判（如 L01 的压缩只是隐喻）</td></tr><tr><td><strong>字数与表达</strong></td><td>&lt; 300 字 / 词不达意</td><td>400+ 字 + 可读</td><td>500+ 字 + 引用具体公式 / 案例</td></tr></tbody></table><p><strong>典型扣分点</strong>：</p><ul><li>把&quot;压缩&quot;说成单一概念（应识别启发式压缩 ≠ 显式 loss ≠ 几何压缩 ≠ 注意力压缩）</li><li>漏掉&quot;优化器&quot;在 L03 中的地位</li><li>把 L11 与 L12 说成同一回事（向量空间不等同于 Self-Attention）</li></ul><hr><h2 id="整卷评分尺度" tabindex="-1">整卷评分尺度 <a class="header-anchor" href="#整卷评分尺度" aria-label="Permalink to &quot;整卷评分尺度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>总分</th><th>等级</th><th>行动</th></tr></thead><tbody><tr><td>90–100</td><td>A+</td><td>可作为助教候选 / 优秀样卷收录</td></tr><tr><td>80–89</td><td>A</td><td>优秀，可推进幕四</td></tr><tr><td>70–79</td><td>B</td><td>合格，建议补强简答薄弱环节</td></tr><tr><td>60–69</td><td>C</td><td>及格，强烈建议在进入幕四前重做 Q11–Q15</td></tr><tr><td>&lt; 60</td><td>F</td><td>不及格，回到对应讲次重学，30 天后重考</td></tr></tbody></table><hr><h2 id="出题来源透明度" tabindex="-1">出题来源透明度 <a class="header-anchor" href="#出题来源透明度" aria-label="Permalink to &quot;出题来源透明度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>讲次</th><th>直接题</th><th>跨讲题</th><th>总占比</th></tr></thead><tbody><tr><td>L00</td><td>0</td><td>0</td><td>0%</td></tr><tr><td>L01</td><td>1 (Q1)</td><td>1 (Q11)</td><td>6%</td></tr><tr><td>L02</td><td>1 (Q2)</td><td>1 (Q16)</td><td>6%</td></tr><tr><td>L03</td><td>1 (Q3)</td><td>2 (Q12, Q18)</td><td>9%</td></tr><tr><td>L04</td><td>1 (Q4)</td><td>0</td><td>3%</td></tr><tr><td>L05</td><td>0</td><td>0</td><td>0%</td></tr><tr><td>L06</td><td>0</td><td>0</td><td>0%</td></tr><tr><td>L07</td><td>1 (Q5)</td><td>1 (Q13)</td><td>6%</td></tr><tr><td>L08</td><td>0</td><td>0</td><td>0%</td></tr><tr><td>L09</td><td>0</td><td>0</td><td>0%</td></tr><tr><td>L10</td><td>0</td><td>0</td><td>0%</td></tr><tr><td>L11</td><td>1 (Q6)</td><td>2 (Q14, Q18)</td><td>9%</td></tr><tr><td>L12</td><td>2 (Q7, Q8)</td><td>2 (Q13, Q18)</td><td>17%</td></tr><tr><td>L13</td><td>0</td><td>0</td><td>0%</td></tr><tr><td>L14</td><td>1 (Q9)</td><td>2 (Q15, Q17)</td><td>9%</td></tr><tr><td>L15</td><td>0</td><td>0</td><td>0%</td></tr><tr><td>L16</td><td>1 (Q10)</td><td>1 (Q17)</td><td>6%</td></tr></tbody></table><p><strong>覆盖盲区</strong>（设计选择，非疏漏）：</p><ul><li>L05 / L06 / L08 / L09 / L10 / L13 / L15：这些讲次的内容已通过相邻讲次的跨讲题间接考察，避免单卷题量爆炸</li><li>期末考试将补充对 L05 (结构化数据)、L13 (BERT vs GPT)、L15 (预训练) 的直接考察</li></ul>',42)])])}const b=d(e,[["render",l]]);export{g as __pageData,b as default};
